# 5급 CH3 be동사와 일반동사 과거 (21~30) 2차 감수
X(5, 21, r="과거의 문장은 동사의 과거형(-ed, 불규칙 과거형, was/were, did)을 쓴다. 현재형(-s, 동사원형)은 지금의 습관·사실을 나타낸다.",
  n=["last night이 있고 hit은 과거형으로도 쓰이므로", "didn't로 과거를 나타내므로", "Were로 과거를 묻고 있으므로", "studies는 현재형이라 과거가 아니므로", "worked는 과거형이므로"],
  st="① 문장마다 동사의 형태를 본다. hit처럼 현재형과 과거형이 같은 동사는 last night 같은 때를 나타내는 말로 가른다. → ② 과거형(-ed, 불규칙, was/were, did)인 문장을 지운다. → ③ {0} 정답은 {n}.",
  R="④의 studies는 3인칭 단수 현재형이다.", B="⑤의 leaves는 현재형이고 every morning도 지금의 습관을 나타낸다.", C="①의 plays는 현재형이고 every day도 지금의 습관을 나타낸다.", D="⑤의 reads는 현재형이고 now도 지금을 나타낸다.",
  E="④의 go는 현재형이고 every day도 지금의 습관을 나타낸다.", F="⑤의 watches는 현재형이고 every night도 지금의 습관을 나타낸다.")
RV(5, 21, "CDEF", v="수정(내용)", why="정답 확인. 다만 정답 문장(현재형)과 같은 문장의 과거형이 다른 보기에 함께 있어(Tom plays / Tom played, Jane read / Jane reads, They went / They go, My dad watched / My dad watches) 둘만 견주면 답이 나온다. 원문항에는 이런 짝 문장이 없다.", fix="짝이 되는 문장을 다른 문장으로")

X(5, 22, r="불규칙 과거형: teach - taught, ride - rode, fly - flew, hit - hit. 규칙 과거형은 -ed를 붙인다(stop - stopped).",
  n=["teach의 불규칙 과거형 taught로 옳으므로", "ride의 불규칙 과거형 rode로 옳으므로", "fly의 과거형은 flied가 아니라 flew이므로", "p를 겹쳐 쓰고 -ed를 붙인 옳은 형태이므로", "hit은 현재형과 과거형이 같으므로"],
  st="① 짝마다 과거형이 맞는지 본다. 불규칙 동사에 -ed를 붙인 것을 찾는다. → ② {0} → ③ 정답은 {a}.",
  R="fly는 불규칙 동사라 과거형이 flew다. flied는 없는 형태다.", B="take는 불규칙 동사라 과거형이 took이다.", C="go는 불규칙 동사라 과거형이 went다.", D="buy는 불규칙 동사라 과거형이 bought다.", E="see는 불규칙 동사라 과거형이 saw다.",
  F="make는 불규칙 동사라 과거형이 made다.")

X(5, 23, r="be동사의 과거형: 단수 주어·I는 was, 복수 주어·you는 were. buy의 과거형은 bought다.",
  n=["buyed라는 형태는 없으므로", "단수 주어 Penelope에 was, buy의 과거형 bought가 알맞으므로", "단수 주어에 were를 쓸 수 없고 buyed도 없는 형태이므로", "단수 주어 Penelope에 were를 쓸 수 없으므로", "before가 있어 현재형 is를 쓸 수 없고 brought는 bring의 과거형이므로"],
  st="① 첫 빈칸: 과거의 일이고 주어가 {0}. → ② 둘째 빈칸: 일반동사의 과거형을 쓴다: {1}. → ③ 정답은 {a}.",
  R=("Penelope(단수)이므로 was", "buy - bought"), B=("The road(단수)이므로 was", "drive - drove"), C=("Tom(단수)이므로 was", "buy - bought"), D=("They(복수)이므로 were", "see - saw"), E=("I이므로 was", "eat - ate"),
  F=("Jane(단수)이므로 was", "make - made"))

X(5, 24, r="불규칙 동사의 과거형은 -ed를 붙이지 않는다: grow - grew, teach - taught, write - wrote, catch - caught.",
  n=["teach의 과거형 taught로 옳으므로", "stay의 과거형 stayed로 옳으므로", "write의 과거형 wrote로 옳으므로", "live의 과거형 lived로 옳으므로", "grow의 과거형은 growed가 아니라 grew이므로"],
  st="① 문장마다 동사의 과거형이 바른지 본다. → ② 불규칙 동사에 -ed를 붙인 것을 찾는다. {0} → ③ 정답은 {n}.",
  R="grow의 과거형은 grew다.", B="catch의 과거형은 caught다.", C="go의 과거형은 went다. ④의 went와 견주어도 알 수 있다.", D="buy의 과거형은 bought다. ③의 bought와 견주어도 알 수 있다.", E="see의 과거형은 saw다. ④의 saw와 견주어도 알 수 있다.",
  F="make의 과거형은 made다.")

X(5, 25, r="Did, didn't, Does 뒤에는 동사원형을 쓴다. 과거의 일은 긍정문에서만 동사의 과거형으로 나타낸다.",
  n=["Did 뒤에는 had가 아니라 동사원형 have를 쓰므로", "see의 과거형 saw를 바르게 썼으므로", "didn't 뒤에는 felt가 아니라 동사원형 feel을 쓰므로", "Did 뒤에는 rode가 아니라 동사원형 ride를 쓰므로", "Does 뒤에는 wrote가 아니라 동사원형 write를 쓰므로"],
  st="① Did, didn't, Does가 있는 문장은 뒤의 동사가 원형인지 본다. → ② 조동사가 없는 문장은 과거형이 바른지 본다. → ③ {0} 정답은 {n}.",
  R="②만 조동사 없이 과거형 saw를 바르게 썼다.", B="④만 take의 과거형 took을 바르게 썼다.", C="⑤만 go의 과거형 went를 바르게 썼다.", D="④만 buy의 과거형 bought를 바르게 썼다.", E="③만 복수 주어 We에 were를 바르게 썼다.",
  F="③만 eat의 과거형 ate를 바르게 썼다.")

X(5, 26, r="yesterday처럼 과거의 때를 나타내는 말이 있으면 동사의 과거형을 쓴다. go의 과거형은 went다.",
  n=["go는 현재형이라 ‘갔다’가 되지 않으므로", "goes는 현재형이므로", "go의 과거형 went가 ‘갔다’의 뜻이 되므로", "going만으로는 동사 자리를 채울 수 없으므로", "gone은 과거분사라 혼자 동사 자리에 쓸 수 없으므로"],
  st="① 우리말과 때를 나타내는 말을 본다: {0}. 과거의 일이다. → ② 동사의 과거형을 쓴다: {1}. → ③ 정답은 {a}.",
  R=("‘갔다’, yesterday", "go - went"), B=("‘과거형’을 넣으라는 발문, yesterday", "write - wrote"), C=("‘과거형’을 넣으라는 발문, yesterday", "buy - bought"), D=("‘과거형’을 넣으라는 발문", "eat - ate"), E=("‘과거형’을 넣으라는 발문", "see - saw"),
  F=("‘과거형’을 넣으라는 발문, yesterday", "make - made"))
RV(5, 26, "B", v="수정(내용)", why="정답 확인. 다만 오답 writed는 영어에 없는 형태라 철자만 보고 지워진다. 원문항의 오답(go, goes, going, gone)은 모두 실제 형태다. 발문이 ‘올바른 과거형’이라고 시제를 알려 주는 점도 원문항과 다르다.", fix="writed를 writing으로, 발문을 원문항처럼 우리말 뜻 제시로")

X(5, 27, r="일반동사 과거 부정문은 주어 + didn't(did not) + 동사원형이다.",
  n=["didn't 뒤에는 went가 아니라 동사원형 go를 쓰므로", "didn't + 동사원형 go로 바르게 고쳤으므로", "an hour ago가 있는 과거의 일에 doesn't를 쓸 수 없으므로", "일반동사의 부정에 was를 쓸 수 없으므로", "didn't 뒤에 goes를 쓸 수 없으므로"],
  st="① 동사를 본다: {0}. 일반동사의 과거형이다. → ② 과거 부정은 didn't를 쓰고 뒤의 동사는 원형으로 돌린다: didn't {1}. → ③ 정답은 {n}.",
  R=("went", "go"), B=("ate", "eat"), C=("bought", "buy"), D=("saw", "see"), E=("ate", "eat"), F=("made", "make"))
RV(5, 27, "CDEF", v="수정(내용)", why="정답 확인. 다만 오답 하나(Tom buy ~, They see ~, Jane eat ~, We make ~)는 부정문이 아니어서 ‘부정문으로 고친 것’이라는 발문만 보고 지워진다. 원문항의 오답은 모두 not을 잘못 쓴 문장이다.", fix="그 오답을 not을 잘못 쓴 문장으로")

X(5, 28, r="be동사의 과거형은 단수 주어에 was, 복수 주어에 were를 쓴다. break의 과거형은 broke다.",
  n=["과거의 일이므로 break가 아니라 broke를 써야 하므로", "뒤 문장이 과거라 is를 쓸 수 없으므로", "단수 주어 The wind에 were를 쓸 수 없으므로", "단수 주어 The wind에 was, break의 과거형 broke가 알맞으므로", "breaked라는 형태는 없으므로"],
  st="① (A): 주어가 {0}. → ② (B): 앞 문장과 이어지는 과거의 일이므로 과거형을 쓴다: {1}. → ③ 정답은 {a}.",
  R=("The wind(단수)이므로 was", "break - broke"), B=("The children(복수)이므로 were", "cheer - cheered"), C=("The boys(복수)이므로 were", "eat - ate"), D=("Jane(단수)이므로 was", "go - went"), E=("We(복수)이므로 were", "get - got"),
  F=("Tom(단수)이므로 was", "make - made"))

X(5, 29, r="be동사의 과거형은 주어에 맞춘다: 단수 주어 was, 복수 주어 were. 의문사 의문문에서도 주어는 be동사 뒤에 있다.",
  n=["주어는 your가 아니라 your friends이므로", "주어 your friends가 3인칭 복수라 were를 써야 하므로", "일반동사가 없는 be동사 문장이라 did를 쓰지 않으므로", "yesterday가 있어 현재형 are를 쓸 수 없으므로", "yesterday가 있어 현재형 is를 쓸 수 없고 주어도 복수이므로"],
  st="① 의문문이므로 주어는 be동사 뒤에 있다: {0}. → ② {1} → ③ 이 이유를 말한 것은 {n}.",
  R=("your friends", "복수 주어이고 yesterday가 있으므로 were가 맞다."), B=("the students", "복수 주어이므로 were가 맞다."), C=("Tom", "단수 주어이므로 was가 맞다."), D=("the boys", "복수 주어이므로 were가 맞다."), E=("Jane", "단수 주어이므로 was가 맞다."),
  F=("they", "복수 주어이므로 were가 맞다."))
RV(5, 29, "B", fx=True, why="수정 예시의 오답 ④(형용사 late가 여러 명의 상태를 나타내므로 were로 고쳐야 한다)는 고친 결과(were)가 옳아 정답과 헷갈릴 수 있었다. 분명히 틀린 설명으로 바꿨다.")

X(5, 30, r="didn't/Did 뒤에는 동사원형을 쓴다. 일반동사 앞에 be동사를 함께 쓰지 않는다. read는 과거형도 read다.",
  pre=["문장별 판정: (가) O. read는 과거형도 read다. (나) X. didn't 뒤에는 동사원형 read. (다) O. Does + 주어 + 동사원형. (라) X. was와 read를 함께 쓸 수 없다(They read ~). (마) O. Did + 주어 + 동사원형."],
  n=["(가)는 옳은 문장이므로", "(나)와 (라)가 모두 틀렸으므로", "(다)는 옳은 문장이므로", "(마)는 옳은 문장이므로", "(가), (다) 모두 옳은 문장이므로"],
  st="① did/didn't/Does가 있는 문장은 뒤가 동사원형인지 본다. → ② be동사 문장은 주어와 수가 맞는지, 일반동사와 겹쳐 쓰지 않았는지 본다. → ③ {0} 정답은 {a}.",
  R="(나) didn't readed, (라) was read가 틀렸다.", B="(나) did not ate(eat), (다) The boys was(were)가 틀렸다.", C="(가) buyed(bought)만 틀렸다.", D="(다) Did they went(go)만 틀렸다.", E="(라) goed(went)만 틀렸다.",
  F="(가) maked(made), (나) didn't saw(see), (라) taked(took)가 틀렸다.")
